I18n.add({fr:{"Jumpy Frog":"Grenouille sauteuse","🐸 Jumpy Frog":"🐸 Grenouille sauteuse","Tap or press Space to start!":"Touche l'écran ou appuie sur Espace pour commencer !","⬆️ Jump!":"⬆️ Saute !","Tap the game, press the Jump button, or press Space / ⬆️ to jump over the rocks.":"Touche le jeu, le bouton Saute, ou appuie sur Espace / ⬆️ pour sauter par-dessus les cailloux.","Jump! 🐸":"Saute ! 🐸","{n} rocks! Super! 🌟":"{n} cailloux ! Super ! 🌟","Bonk! You jumped {n} rocks. Tap to try again!":"Bong ! Tu as sauté {n} cailloux. Touche pour réessayer !"},"zh-HK":{"Jumpy Frog":"跳跳青蛙","🐸 Jumpy Frog":"🐸 跳跳青蛙","Tap or press Space to start!":"撳一下或者撳空白鍵就開始！","⬆️ Jump!":"⬆️ 跳！","Tap the game, press the Jump button, or press Space / ⬆️ to jump over the rocks.":"撳遊戲畫面、撳「跳」掣，或者撳空白鍵 / ⬆️，跳過啲石頭。","Jump! 🐸":"跳！🐸","{n} rocks! Super! 🌟":"{n} 粒石頭！超勁！🌟","Bonk! You jumped {n} rocks. Tap to try again!":"嘭！你跳過咗 {n} 粒石頭。撳一下再玩！"}});